<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { http, createCommandIntent } from '@/api/http'
import { allRecords } from '@/api/pagination'
import { getToken, getCountryId } from '@/utils/session'
import StatusTag from '@/components/StatusTag.vue'
import { useUserStore } from '@/stores/user'
import { useOptionsStore, type OptionItem } from '@/stores/options'
const mockMode = import.meta.env.MODE === 'demo' && import.meta.env.VITE_USE_MOCK === 'true'
const user = useUserStore(), options = useOptionsStore(), saveIntent = createCommandIntent(), confirmIntent = createCommandIntent()
const rows = ref<Record<string, any>[]>([]), accounts = ref<Record<string, any>[]>([]), books = ref<Record<string, any>[]>([]), bookId = ref<number>(), saving = ref(false)
const currencies = ref<Record<string, any>[]>([])
const baseDecimals = computed(() => currencies.value.find(c => c.code === books.value.find(b => b.id === bookId.value)?.baseCurrency)?.decimals ?? 2)
const origDecimals = computed(() => currencies.value.find(c => c.code === form.currency)?.decimals ?? 2)
const editing = ref<number>(), version = ref<number>()
const form = reactive({ accountId: null as number | null, amount: null as number | null, direction: 'DEBIT', cutoffDate: '', currency: '', origAmount: null as number | null, rate: 1, aux: {} as Record<string, any> })
const auxOptions = ref<Record<string, OptionItem[]>>({})
const definitions: Record<string, { label: string; url: string }> = { customerId: { label: '客户', url: '/md/customers' }, supplierId: { label: '供应商 / 物流商', url: '/md/partners' }, fundAccountId: { label: '资金账户', url: '/md/fund-accounts' }, productId: { label: '商品', url: '/md/products' }, warehouseId: { label: '仓库', url: '/org/warehouses' }, storeId: { label: '门店', url: '/org/stores' }, expenseItemId: { label: '费用项目', url: '/md/expense-items' }, employeeId: { label: '员工', url: '/sys/users' } }
const aliases: Record<string, string> = { CUSTOMER: 'customerId', PARTNER: 'supplierId', SUPPLIER: 'supplierId', FUND: 'fundAccountId', PRODUCT: 'productId', WAREHOUSE: 'warehouseId', STORE: 'storeId', EXPENSE: 'expenseItemId', EMPLOYEE: 'employeeId' }
const selected = computed(() => accounts.value.find(a => a.id === form.accountId)), auxFields = computed<string[]>(() => (selected.value?.auxTypes || []).map((t: string) => aliases[t] || t))
const totals = computed(() => ({ debit: rows.value.filter(r => r.direction === 'DEBIT').reduce((s, r) => s + Number(r.baseAmount || 0), 0), credit: rows.value.filter(r => r.direction === 'CREDIT').reduce((s, r) => s + Number(r.baseAmount || 0), 0) }))
async function load() { if (!bookId.value) return; rows.value = (await allRecords<Record<string, any>>('/fin/opening-balances', { bookId: bookId.value })); accounts.value = (await allRecords<Record<string, any>>('/fin/accounts', { bookId: bookId.value })).filter(a => a.isLeaf && a.status === 'ENABLED'); form.currency = books.value.find(b => b.id === bookId.value)?.baseCurrency || ''; form.accountId = null; form.aux = {}; editing.value = version.value = undefined; saveIntent.reset(); confirmIntent.reset() }
async function choose() { form.aux = {}; form.currency = books.value.find(b => b.id === bookId.value)?.baseCurrency || ''; form.origAmount = null; form.rate = 1; form.direction = selected.value?.direction || 'DEBIT'; for (const field of auxFields.value) if (definitions[field] && !auxOptions.value[field]) auxOptions.value[field] = await options.remote(definitions[field].url, field === 'employeeId' ? 'displayName' : 'name', 'id', { size: 200 }) }
async function add() { if (!form.accountId || form.amount === null || !form.cutoffDate) { ElMessage.warning('请选择科目，明确金额和期初截止日期'); return } saving.value = true; try { const payload = { ...form, origAmount: selected.value?.fxEnabled && form.currency !== books.value.find(b => b.id === bookId.value)?.baseCurrency ? form.origAmount : form.amount, rate: form.currency === books.value.find(b => b.id === bookId.value)?.baseCurrency ? 1 : form.rate }; if (editing.value) await http.putIdem('/fin/opening-balances/' + editing.value + '?bookId=' + bookId.value, { ...payload, version: version.value }, saveIntent); else await http.postIdem('/fin/opening-balances?bookId=' + bookId.value, payload, saveIntent); await load(); ElMessage.success('期初草稿已保存，尚未确认') } finally { saving.value = false } }
async function edit(row: Record<string, any>) { editing.value = row.id; version.value = row.version; Object.assign(form, { accountId: row.accountId, amount: row.baseAmount, direction: row.direction, cutoffDate: row.cutoffDate, currency: row.currency, origAmount: row.origAmount, rate: row.rate, aux: JSON.parse(JSON.stringify(row.aux)) }); saveIntent.reset(); for (const field of auxFields.value) if (definitions[field] && !auxOptions.value[field]) auxOptions.value[field] = await options.remote(definitions[field].url, field === 'employeeId' ? 'displayName' : 'name', 'id', { size: 200 }) }
async function remove(row: Record<string, any>) { await ElMessageBox.confirm('删除这条未确认期初草稿？', '删除期初草稿', { type: 'warning' }); await saveIntent.run(`${getToken()}:${getCountryId()}`, 'DELETE /fin/opening-balances/' + row.id, { version: row.version, bookId: bookId.value }, key => http.delete('/fin/opening-balances/' + row.id, { params: { version: row.version, bookId: bookId.value }, headers: { 'Idempotency-Key': key } })); await load() }
async function confirm() { await ElMessageBox.confirm(`确认本账套期初：借 ${totals.value.debit.toFixed(baseDecimals.value)}，贷 ${totals.value.credit.toFixed(baseDecimals.value)}？确认后参与账簿且不能直接修改。`, '确认期初', { type: 'warning' }); saving.value = true; try { const res = await http.postIdem<{ debit: number; credit: number }>('/fin/opening-balances/confirm?bookId=' + bookId.value, {}, confirmIntent); ElMessage.success(`已确认：借 ${res.debit} = 贷 ${res.credit}`); await load() } finally { saving.value = false } }
onMounted(async () => { [books.value, currencies.value] = await Promise.all([http.get<Record<string, any>[]>('/fin/books'), allRecords<Record<string, any>>('/md/currencies')]); if (books.value.length === 1) bookId.value = books.value[0]!.id; await load() })
</script>
<template>
  <el-card><template #header>期初余额</template><el-alert title="请以经核对的期初资料录入；保存草稿与确认期初是两个独立操作。" :closable="false" />
    <el-form inline style="margin-top: 16px"><el-form-item label="账套"><el-select v-model="bookId" placeholder="请选择账套" style="width:260px;max-width:100%" @change="load"><el-option v-for="b in books" :key="b.id" :label="b.name" :value="b.id" /></el-select></el-form-item></el-form>
    <el-form v-if="user.hasPerm('fin:opening:edit') && bookId" inline><el-form-item label="截止日期"><el-date-picker v-model="form.cutoffDate" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="科目"><el-select v-model="form.accountId" filterable @change="choose"><el-option v-for="a in accounts" :key="a.id" :label="a.code + ' ' + a.name" :value="a.id" /></el-select></el-form-item><el-form-item label="方向"><el-select v-model="form.direction" style="width: 90px"><el-option label="借" value="DEBIT" /><el-option label="贷" value="CREDIT" /></el-select></el-form-item><el-form-item label="本位币金额"><el-input-number v-model="form.amount" :min="0" :precision="baseDecimals" /></el-form-item>
      <el-form-item v-for="field in auxFields" :key="field" :label="definitions[field]?.label || field"><el-select v-model="form.aux[field]" filterable><el-option v-for="o in auxOptions[field] || []" :key="String(o.value)" :label="o.label" :value="o.value" /></el-select></el-form-item>
      <template v-if="selected?.fxEnabled"><el-form-item label="原币"><el-input v-model="form.currency" style="width: 90px" /></el-form-item><el-form-item label="原币金额"><el-input-number v-model="form.origAmount" :min="0" :precision="origDecimals" /></el-form-item><el-form-item label="汇率"><el-input-number v-model="form.rate" :min="0" :precision="8" /></el-form-item></template><el-button :loading="saving" @click="add">{{ editing ? '保存修改' : '保存期初草稿' }}</el-button><el-button v-if="editing" @click="load">取消修改</el-button>
    </el-form><p>借方 {{ totals.debit.toFixed(baseDecimals) }} · 贷方 {{ totals.credit.toFixed(baseDecimals) }}</p><el-button v-if="user.hasPerm('fin:opening:edit')" type="primary" :disabled="!rows.length || !rows.some(r => r.status === 'DRAFT')" :loading="saving" @click="confirm">试算并确认期初</el-button>
    <el-table :data="rows" size="small"><el-table-column prop="accountCode" label="科目" width="90" /><el-table-column prop="accountName" label="名称" /><el-table-column prop="cutoffDate" label="截止日期" /><el-table-column prop="direction" label="方向" width="90" /><el-table-column prop="auxKey" label="辅助项" /><el-table-column prop="currency" label="币种" width="90" /><el-table-column prop="baseAmount" label="本位币" /><el-table-column label="状态" width="100"><template #default="{ row }"><StatusTag :status="row.status" /></template></el-table-column><el-table-column v-if="!mockMode && user.hasPerm('fin:opening:edit')" label="操作"><template #default="{ row }"><template v-if="row.status === 'DRAFT'"><el-button link @click="edit(row)">修改</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></template></el-table-column></el-table>
  </el-card>
</template>
